// The one writing rule reader for the JavaScript surfaces.
//
// The rule table itself is generated by the compiled wall set in the Rust admit
// crate and written to AEP-Components/admit/rules/writing-rules.json, so a
// JavaScript surface never carries a private copy of a writing rule. Every
// JavaScript surface that used to hold its own dash list, Oxford comma list or
// punctuation scan reads this module instead.

import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const TABLE_PATH = join(
  dirname(fileURLToPath(import.meta.url)),
  "..",
  "rules",
  "writing-rules.json",
);

let cachedRules = null;

export function writingRulesPath() {
  return TABLE_PATH;
}

/** The one rule table. Shape: id, wall_id, reason, detector, code_points, patterns. */
export function writingRuleTable() {
  if (cachedRules === null) {
    const parsed = JSON.parse(readFileSync(TABLE_PATH, "utf8"));
    cachedRules = parsed.rules ?? [];
  }
  return cachedRules;
}

export function writingRuleIds() {
  return writingRuleTable().map((rule) => rule.id);
}

export function writingRule(id) {
  const rule = writingRuleTable().find((entry) => entry.id === id);
  if (!rule) throw new Error(`unknown writing rule: ${id}`);
  return rule;
}

export function writingWallId(rule) {
  return `writing:${rule}`;
}

function hasCodePoint(text, points) {
  return (points ?? []).some((point) => text.includes(String.fromCodePoint(point)));
}

function hasPattern(text, patterns) {
  return (patterns ?? []).some((pattern) => pattern !== "" && text.includes(pattern));
}

function isUrlByte(ch) {
  return /[A-Za-z0-9]/.test(ch) || "-._~:/?#[]@!$&'()*+,;=%".includes(ch);
}

/** Indexes inside a URL token or a query string. Same spans as the Admit wall. */
export function protectedWritingTokenMask(text) {
  const chars = Array.from(String(text ?? ""));
  const n = chars.length;
  const mask = new Array(n).fill(false);
  let i = 0;
  while (i < n) {
    if (/[A-Za-z]/.test(chars[i] ?? "")) {
      let j = i + 1;
      while (j < n && (/[A-Za-z0-9]/.test(chars[j] ?? "") || "+-.".includes(chars[j] ?? ""))) {
        j += 1;
      }
      if (j + 2 < n && chars[j] === ":" && chars[j + 1] === "/" && chars[j + 2] === "/") {
        let k = j + 3;
        while (k < n && isUrlByte(chars[k] ?? "")) k += 1;
        for (let t = i; t < k; t += 1) mask[t] = true;
        i = k;
        continue;
      }
    }
    i += 1;
  }
  let q = 0;
  while (q < n) {
    if (chars[q] === "?" && !mask[q]) {
      let k = q + 1;
      let hasBinding = false;
      while (k < n && isUrlByte(chars[k] ?? "") && chars[k] !== "?") {
        if (chars[k] === "=" || chars[k] === "&") hasBinding = true;
        k += 1;
      }
      if (hasBinding) {
        let start = q;
        while (
          start > 0 &&
          !mask[start - 1] &&
          isUrlByte(chars[start - 1] ?? "") &&
          chars[start - 1] !== "?"
        ) {
          start -= 1;
        }
        for (let t = start; t < k; t += 1) mask[t] = true;
        q = k;
        continue;
      }
    }
    q += 1;
  }
  return mask;
}

/** Missing space after ? or ! before the next word, the kernel punctuation rule. */
export function punctuationWordSpaceClosed(text) {
  const chars = Array.from(String(text ?? ""));
  const mask = protectedWritingTokenMask(text);
  for (let i = 0; i < chars.length - 1; i += 1) {
    if (mask[i]) continue;
    const ch = chars[i];
    const next = chars[i + 1];
    if ((ch === "?" || ch === "!") && /[A-Za-z0-9]/.test(next)) return true;
  }
  return false;
}

/** One verdict per rule, read from the table. */
export function writingRuleClosed(text, id) {
  const rule = writingRule(id);
  if (rule.detector === "punct_word_space") return punctuationWordSpaceClosed(text);
  return hasCodePoint(text, rule.code_points) || hasPattern(text, rule.patterns);
}

/** Closed walls for one text, in rule table order. */
export function compileWritingWalls(text) {
  const body = String(text ?? "");
  return writingRuleTable().map((rule) => ({
    id: rule.wall_id,
    closed: writingRuleClosed(body, rule.id),
    reason: rule.reason,
  }));
}

/** Violations for one text or for one line of a larger document. */
export function lintWritingRules(text) {
  const body = String(text ?? "");
  const violations = [];
  for (const rule of writingRuleTable()) {
    if (writingRuleClosed(body, rule.id) === false) continue;
    violations.push({ rule: rule.id, message: rule.reason, wall_id: rule.wall_id });
  }
  return violations;
}
